const r = await api.get('/mails', { limit: 100 }); // assume limit param works
const mails = r.items;
if (!mails || mails.length===0) {
  return 'No mails found';
}
// find most recent by received_at
let latest = mails[0];
for (const m of mails) {
  if (new Date(m.received_at) > new Date(latest.received_at)) {
    latest = m;
  }
}
return latest.from_email;

